import { useEffect, useMemo, useState } from 'react';
import { Badge, Button, ChipFilter, CopyButton, Dialog, Input, SegmentedControl } from '@nabuxai/ui-react';
import { Section } from '../Section';
import { useLang, useTr } from '../lang';

/*
 * The MotionSites gallery: the 813 MotionSites prompts ported to live NabuXUI
 * scenes (packages/motionsites). The index is generated by
 * packages/motionsites/scripts/build.mjs; the scenes, thumbnails and prompts
 * are served next to the app under ./motionsites/ by the vite plugin in
 * vite.config.ts, and every scene runs in a sandboxed iframe.
 */

type Pair = { fa: string; en: string };
interface Item { slug: string; group: string; title: Pair; oneLiner: Pair; js: boolean; thumb: boolean }
type Index = { groups: Record<string, Pair & { icon: string }>; items: Item[] };
const EMPTY: Index = { groups: {}, items: [] };

/**
 * Where the scene files live: next to the dev server's root, or next to the
 * built bundle (dist/assets/x.js → dist/motionsites/). The path sits in a
 * variable on purpose: a literal `new URL('…', import.meta.url)` is rewritten
 * by Vite into an asset import.
 */
const SCENES_DIR = '../motionsites/';
const BASE = import.meta.env.DEV ? '/motionsites/' : new URL(SCENES_DIR, import.meta.url).href;
const PAGE = 24;

const fold = (text: string) =>
  text.toLowerCase().normalize('NFKD').replace(/[̀-ͯ]/g, '').replace(/[يى]/g, 'ی').replace(/ك/g, 'ک').replace(/[ً-ٰ‌]/g, '');

function currentTheme() {
  return typeof document === 'undefined' ? '' : document.documentElement.dataset.theme ?? '';
}

function Viewer({ item, onClose }: { item: Item; onClose: () => void }) {
  const tr = useTr();
  const lang = useLang();
  const [width, setWidth] = useState('100%');
  const [prompt, setPrompt] = useState<string | null>(null);
  const [nonce, setNonce] = useState(0);
  const src = `${BASE}${item.slug}.html?lang=${lang}${currentTheme() ? `&theme=${currentTheme()}` : ''}`;

  useEffect(() => {
    let live = true;
    setPrompt(null);
    fetch(`${BASE}prompts/${item.slug}.txt`)
      .then((r) => (r.ok ? r.text() : null))
      .then((text) => live && setPrompt(text))
      .catch(() => live && setPrompt(null));
    return () => {
      live = false;
    };
  }, [item.slug]);

  return (
    <Dialog
      open
      onOpenChange={(open) => !open && onClose()}
      size="full"
      title={item.title[lang]}
      description={item.oneLiner[lang]}
      footer={
        <div className="sc-ms-footer">
          {prompt && (
            <CopyButton value={prompt} variant="secondary" size="sm">
              {tr('کپی پرامپت اصلی', 'Copy original prompt')}
            </CopyButton>
          )}
          <Button variant="secondary" size="sm" icon="external-link" href={src} target="_blank" rel="noopener">
            {tr('تمام‌صفحه', 'Full screen')}
          </Button>
        </div>
      }
    >
      <div className="sc-ms-viewer">
        <div className="sc-ms-bar">
          <SegmentedControl
            size="sm"
            aria-label={tr('عرض پیش‌نمایش', 'Preview width')}
            value={width}
            onValueChange={setWidth}
            options={[
              { value: '100%', label: tr('دسکتاپ', 'Desktop') },
              { value: '820px', label: tr('تبلت', 'Tablet') },
              { value: '390px', label: tr('موبایل', 'Phone') },
            ]}
          />
          <Button variant="ghost" size="sm" icon="play" onClick={() => setNonce((n) => n + 1)}>
            {tr('اجرای دوباره', 'Replay')}
          </Button>
        </div>
        <div className="sc-ms-stage">
          <iframe
            key={nonce}
            className="sc-ms-frame"
            style={{ inlineSize: width }}
            src={src}
            title={item.title[lang]}
            allow="autoplay; fullscreen; clipboard-write; accelerometer; gyroscope"
            sandbox="allow-scripts allow-same-origin allow-popups allow-forms"
          />
        </div>
      </div>
    </Dialog>
  );
}

export function MotionSitesBlocks() {
  const tr = useTr();
  const lang = useLang();
  const [group, setGroup] = useState('all');
  const [query, setQuery] = useState('');
  const [limit, setLimit] = useState(PAGE);
  const [open, setOpen] = useState<Item | null>(null);
  // ~800 entries: the index is its own chunk, fetched when the gallery mounts.
  const [INDEX, setIndex] = useState<Index>(EMPTY);
  useEffect(() => {
    let live = true;
    import('../motionsites/index.json').then((module) => live && setIndex(module.default as Index));
    return () => {
      live = false;
    };
  }, []);

  const filtered = useMemo(() => {
    const needle = fold(query.trim());
    return INDEX.items.filter(
      (item) =>
        (group === 'all' || item.group === group) &&
        (!needle || fold(`${item.title.fa} ${item.title.en} ${item.oneLiner.fa} ${item.oneLiner.en} ${item.slug}`).includes(needle)),
    );
  }, [INDEX, group, query]);

  useEffect(() => setLimit(PAGE), [group, query]);

  const chips = [
    { value: 'all', label: tr('همه', 'All'), count: INDEX.items.length },
    ...Object.entries(INDEX.groups).map(([value, label]) => ({ value, label: label[lang], count: INDEX.items.filter((i) => i.group === value).length })),
  ];

  return (
    <Section
      id="motionsites-blocks"
      eyebrow={tr('موشن‌سایتس', 'MotionSites')}
      title={tr('مجموعهٔ موشن‌سایتس، زنده', 'The MotionSites collection, live')}
      description={tr(
        'پرامپت‌های طراحی وب موشن‌سایتس — لندینگ‌ها، بخش‌ها، صحنه‌های سه‌بعدی HorizonX، کامپوننت‌های 21st.dev و Superdesign — هر کدام به یک صحنهٔ زندهٔ NabuXUI تبدیل شده: دوزبانه، راست‌به‌چپ و پاسخ‌گو. کارت را باز کنید تا صحنه را در سه عرض ببینید و پرامپت اصلی را کپی کنید.',
        'The MotionSites web-design prompts — landing pages, sections, HorizonX 3D scenes, 21st.dev and Superdesign components — each rebuilt as a live NabuXUI scene: bilingual, right-to-left ready and responsive. Open a card to try the scene at three widths and copy its original prompt.',
      )}
    >
      <div className="sc-ms-tools">
        <Input
          type="search"
          startAddon="search"
          value={query}
          onChange={(e) => setQuery(e.target.value)}
          placeholder={tr('جست‌وجو: هیرو، قیمت‌گذاری، سه‌بعدی…', 'Search: hero, pricing, 3D…')}
          aria-label={tr('جست‌وجوی صحنه‌ها', 'Search scenes')}
        />
        <ChipFilter items={chips} value={group} onValueChange={setGroup} aria-label={tr('گروه', 'Group')} />
      </div>

      {filtered.length === 0 ? (
        <p className="sc-ms-empty">{tr('صحنه‌ای با این جست‌وجو پیدا نشد.', 'No scene matches this search.')}</p>
      ) : (
        <div className="sc-ms-grid">
          {filtered.slice(0, limit).map((item) => (
            <button key={item.slug} type="button" className="sc-ms-card" onClick={() => setOpen(item)}>
              <span className="sc-ms-thumb" aria-hidden="true">
                {item.thumb ? <img src={`${BASE}thumbs/${item.slug}.webp`} alt="" loading="lazy" decoding="async" /> : <span>{item.title.en.slice(0, 1)}</span>}
              </span>
              <span className="sc-ms-body">
                <strong>{item.title[lang]}</strong>
                <span>{item.oneLiner[lang]}</span>
                <Badge tone="neutral">
                  {INDEX.groups[item.group]?.[lang]}
                </Badge>
              </span>
            </button>
          ))}
        </div>
      )}

      {filtered.length > limit && (
        <div className="sc-ms-more">
          <Button variant="secondary" icon="chevron-down" onClick={() => setLimit((n) => n + PAGE)}>
            {tr(`نمایش بیشتر · ${Math.min(limit, filtered.length).toLocaleString('fa')} از ${filtered.length.toLocaleString('fa')}`, `Show more · ${limit} of ${filtered.length}`)}
          </Button>
        </div>
      )}

      {open && <Viewer item={open} onClose={() => setOpen(null)} />}
    </Section>
  );
}
